"""Regenerate data/explainers/diversity.json and climate.json (draft explainer pages).
Not part of the build. Inputs, downloaded into a scratch dir (the cwd when run):
  dl/sepkoski.rda    https://raw.githubusercontent.com/palaeoverse/sepkoski/main/data/sepkoski.rda   (jones2022, GPL-3)
  phanda/gmst_co2.csv https://raw.githubusercontent.com/EJJudd/PhanDA/main/5_Outputs/PhanDA_GMSTandCO2_percentiles.csv (judd2024, CC BY 4.0)
  lr04/lr04.txt      https://www.ncei.noaa.gov/pub/data/paleo/contributions_by_author/lisiecki2005/lisiecki2005.txt
Needs pandas + rdata (pip install rdata) in a throwaway venv. Usage: python explainer_data.py <out_dir>
Note: the section texts are hard-coded here; edit them in the JSON afterwards or here before regenerating.
"""
import rdata, json, csv, numpy as np, sys
OUT=sys.argv[1]
# ---- marine genera (Sepkoski 2002 via Jones 2022) ----
d = rdata.read_rda("dl/sepkoski.rda")["sepkoski"].dropna(subset=["max_ma","min_ma"])
mx, mn = d.max_ma.to_numpy(float), d.min_ma.to_numpy(float)
edges = sorted(set(np.round(mx,3)) | set(np.round(mn,3)), reverse=True)
steps=[]; ext={}
for a,b in zip(edges[:-1], edges[1:]):
    inbin=(mx>b+1e-6)&(mn<a-1e-6); n=int(inbin.sum())
    e=int((inbin&(np.abs(mn-b)<1e-3)).sum())
    steps.append([round(-a*1e6), round(-b*1e6), n]); ext[round(b,3)]=(e,n)
def pct(b): e,n=ext[b]; return round(100*e/n)
big5=[("End-Ordovician",443.8,"Hirnantian"),("Late Devonian",358.9,"Famennian"),("End-Permian",251.902,"Changhsingian"),("End-Triassic",201.4,"Rhaetian"),("End-Cretaceous",66.0,"Maastrichtian")]
marks=[{"t":round(-b*1e6),"label":nm,"lost_pct":pct(round(b,3)),"stage":st} for nm,b,st in big5]
for m in marks: print(m)
div={"_doc":"DRAFT data for typeset/explainers/diversity.typ. Generated by agent-notes/explainer_data.py from Sepkoski's compendium as packaged by jones2022 (stage ranges on GTS 2023). 'steps' = [from_year, to_year, genera]: marine animal genera whose range overlaps that interval (range-through count). Marks: lost_pct = share of the genera in the last stage before the boundary whose last appearance is in that stage.",
     "title":"Life in the sea","unit":"marine animal genera","sources":["sepkoski2002","jones2022"],
     "steps":steps,"marks":marks,
     "sections":[
      {"head":"What the graph shows","text":"The number of kinds of sea animals known from each slice of time. Diversity exploded in the Cambrian and Ordovician, held at a plateau through the rest of the Paleozoic, and climbed through the Mesozoic and Cenozoic. Five sharp drops break the climb: the mass extinctions. The worst, at the end of the Permian 252 million years ago, cut known genera by two thirds; their number did not return to its old level until the Jurassic.","sources":["sepkoski2002","raup1982"]},
      {"head":"How it is known","text":"Jack Sepkoski combed the literature for every fossil marine animal genus, with the oldest and youngest rock in which it is found, some 36,000 genera in all. A genus counts as present in every interval between its first and last appearance. Counting genera rather than species smooths over gaps in the record.","sources":["sepkoski2002","jones2022"]},
      {"head":"How sure","text":"The mass extinctions stand out in every analysis. The long rise is less certain: younger rocks are more plentiful, better exposed and better studied. When the counts are corrected for how much rock has been sampled, the late Cenozoic comes out less than twice as diverse as the mid-Paleozoic, against two and a half times in the raw counts.","sources":["raup1982","alroy2008"]}]}
json.dump(div,open(f"{OUT}/diversity.json","w"),ensure_ascii=False,indent=1)
# ---- climate: PhanDA + LR04 ----
rows=list(csv.DictReader(open("phanda/gmst_co2.csv")))
st=[]
for r in rows:
    st.append({"stage":r["Stage"],"from":round(-float(r["LowerAge"])*1e6),"to":round(-float(r["UpperAge"])*1e6),
               "T":[round(float(r[k]),1) for k in ("GMST_05","GMST_50","GMST_95")],
               "CO2":[round(float(r[k])) for k in ("CO2_05","CO2_50","CO2_95")]})
st.sort(key=lambda s:s["from"])
lr=[]
for line in open("lr04/lr04.txt").read().split("Column 1: Time (ka)")[1].split("Error")[1].splitlines():
    p=line.split()
    if len(p)<2:
        if lr: break
        continue
    try: t=float(p[0]); v=float(p[1])
    except ValueError: break
    if t<=1000 and int(t)%2==0: lr.append([round(-t*1000), v])
print(len(st),"stages;",len(lr),"lr04 pts", lr[:2], lr[-1])
for s in st:
    if s["stage"] in ("Turonian","Upper Pleistocene","Hirnantian","Serpukhovian","Induan","PETM","Holocene","Frasnian","Floian","Tremadocian"): print(s)
clim={"_doc":"DRAFT data for typeset/explainers/climate.typ. 'stages' from PhanDA (judd2024; github.com/EJJudd/PhanDA, 5_Outputs/PhanDA_GMSTandCO2_percentiles.csv, CC BY 4.0): global mean surface temperature (°C) and CO2 (ppm) per geological stage as [5th, 50th, 95th] percentiles. 'lr04' = LR04 benthic δ18O stack (lisiecki2005; NOAA NCEI copy), every 2 kyr for the last 1 Myr: [year, ‰]; higher δ18O = more ice and colder deep water. Generated by agent-notes/explainer_data.py.",
      "title":"Hothouse and icehouse","sources":["judd2024","lisiecki2005"],
      "stages":st,"lr04":lr,
      "labels":[],
      "sections":[
       {"head":"What the graph shows","text":"Earth's average surface temperature over the last 485 million years swung between about 11 °C and 36 °C, far wider than anything people have known (about 14 °C before industry). It peaked in the Cretaceous hothouse and in the brief heat spike 56 million years ago, and bottomed out in the ice ages of the late Carboniferous and of the last few million years. Carbon dioxide in the air rose and fell with it.","sources":["judd2024"]},
       {"head":"How it is known","text":"Shells and teeth record the temperature of the water they grew in, in their oxygen isotopes and magnesium content, and some fossil molecules do too. PhanDA blends these measurements with climate-model runs for each geological stage, the same data-assimilation method weather forecasts use. Its CO₂ curve is a compilation of separate CO₂ proxies.","sources":["judd2024"]},
       {"head":"How sure","text":"Each value is the middle of a spread (the grey band holds 90% of the estimates). Data are dense in the Cenozoic, where PhanDA agrees with other methods, and sparse in the early Paleozoic. CO₂ tracks temperature closely: over geological time each doubling went with about 8 °C of warming, with mid-Cretaceous CO₂ the least certain.","sources":["judd2024"]},
       {"head":"Glacial cycles","text":"The zoom shows the last million years from 57 deep-sea cores: ice sheets grew slowly and collapsed quickly about every 100,000 years, a sawtooth paced by Earth's orbit.","sources":["lisiecki2005"]}]}
json.dump(clim,open(f"{OUT}/climate.json","w"),ensure_ascii=False,indent=1)
